import { useState } from "react";
import axios from "axios";
import "./Page.css";

function SearchPage() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!query.trim()) return;

    setLoading(true);
    setHasSearched(true);
    try {
      // Hits a specialized search endpoint or passes a 'q' parameter
      const response = await axios.get(`http://localhost:5000/api/jobs/search?q=${query}`);
      setResults(response.data);
    } catch (err) {
      console.error("Search failed:", err);
    }
    setLoading(false);
  };

  return (
    <div className="page">
      <header className="page-header">
        <h1>Global Opportunity Search</h1>
        <p>Search by company, role, or specific skills (e.g., "Python", "TCS", "ISRO")</p>
      </header>

      {/* Main Search Bar */}
      <div className="search-container">
        <form onSubmit={handleSearch} className="search-form">
          <input
            type="text"
            placeholder="Search jobs, internships, or companies..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="search-input"
          />
          <button type="submit" className="btn-search">
            {loading ? "Searching..." : "Search"}
          </button>
        </form>
      </div>

      {/* Results Section */}
      <div className="jobs-grid">
        {results.length > 0 ? (
          results.map((job) => (
            <div 
              className={`job-card ${job.category === 'Government' ? 'govt-highlight' : ''}`} 
              key={job.jobId}
            >
              {job.category === 'Government' && <span className="govt-badge">Official</span>}
              
              <div className="card-body">
                <span className="source-tag">{job.sourceWebsite}</span>
                <h3 className="job-title">{job.jobTitle}</h3>
                <h4 className="company-name">{job.companyName}</h4>
                
                <div className="job-tags">
                  {job.eligible_branches?.map((b) => (
                    <span key={b} className="branch-tag">{b}</span>
                  ))}
                  <span className="type-tag">{job.jobType}</span>
                </div>
              </div>

              <div className="card-footer">
                <span className="scraped-date">
                  Updated: {new Date(job.scrapedAt).toLocaleDateString()}
                </span>
                <a 
                  href={job.applicationLink} 
                  target="_blank" 
                  rel="noreferrer" 
                  className="apply-link"
                >
                  View Details
                </a>
              </div>
            </div>
          ))
        ) : (
          hasSearched && !loading && (
            <div className="empty-state">
              <p>No results found for "{query}".</p>
              <span>Try searching for general terms like "Developer" or "Mechanical".</span>
            </div>
          )
        )}
      </div>
    </div>
  );
}

export default SearchPage;
